// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 warpTime, uint256 unlockParam, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        unlockParam = bound(unlockParam, 0, 2);
        vm.warp(warpTime);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockParam);
        (uint256 unlockTime,) = c.Acc(actor);
        assertTrue(unlockTime >= block.timestamp);
    }
}
